@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Jost:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Luxury — deep ink, champagne gold, high-contrast serif, hairline rules */
.theme-luxury {
  --bg: oklch(0.174 0.007 78.1);
  --surface: oklch(0.206 0.011 80.5);
  --surface-2: oklch(0.246 0.014 81.6);
  --fg: oklch(0.930 0.022 83.3);
  --fg-muted: oklch(0.655 0.033 81.7);
  --accent: oklch(0.726 0.097 85.4);
  --accent-fg: oklch(0.174 0.007 78.1);
  --accent-2: oklch(0.570 0.065 82.9);
  --line: oklch(0.72 0.06 85 / 30%);
  --success: oklch(0.72 0.12 155);
  --warning: oklch(0.82 0.13 85);
  --danger: oklch(0.6 0.19 22);

  --radius: 0.125rem;
  --radius-sm: 0.0625rem;
  --radius-lg: 0.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 0 oklch(0.72 0.06 85 / 20%);
  --shadow-2: 0 18px 40px -24px oklch(0 0 0 / 85%);
  --shadow-3: 0 34px 80px -34px oklch(0 0 0 / 90%);
  --glow: 0 0 0 1px var(--line), 0 0 30px -12px oklch(0.82 0.12 88 / 55%);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Jost", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.3em;

  background-color: var(--bg);
  background-image: radial-gradient(60rem 40rem at 50% -20%, oklch(0.82 0.12 88 / 10%), transparent 70%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-luxury h1,
.theme-luxury h2,
.theme-luxury h3 {
  font-family: var(--font-display);
  font-weight: 300;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-luxury h1 { font-weight: 300; letter-spacing: 0.03em; }
.theme-luxury button { text-transform: uppercase; letter-spacing: 0.22em; font-weight: 500; }
.theme-luxury h2 { font-weight: 400; }
.theme-luxury ::selection { background: oklch(0.75 0.09 85); color: oklch(0.15 0 0); }
.theme-luxury h1 { color: #efe7d8; } .theme-luxury h2 { color: var(--accent); }

/* depth */
.theme-luxury thead th { text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.65em; font-weight: 500; color: var(--accent); border-bottom: 1px solid var(--line); text-align: left; }
.theme-luxury td { border-bottom: 1px solid oklch(0.72 0.06 85 / 15%); }
.theme-luxury tbody tr { transition: background 250ms ease; }
.theme-luxury tbody tr:hover { background: oklch(0.726 0.097 85.4 / 7%); }
.theme-luxury input, .theme-luxury select, .theme-luxury textarea { background: transparent; border: 1px solid var(--line); border-radius: var(--radius-sm); color: var(--fg); transition: border-color 250ms ease, box-shadow 250ms ease; }
.theme-luxury input:focus, .theme-luxury select:focus, .theme-luxury textarea:focus { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-luxury a { color: var(--accent); text-decoration: none; }
/* physical: hairline underline draws in gold on hover, offset like an engraving */
.theme-luxury a:hover { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 5px; text-decoration-color: var(--accent); }
.theme-luxury kbd { font-family: var(--font-mono); font-size: 0.8em; padding: 0.12em 0.5em; border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-2); color: var(--accent); }
.theme-luxury ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-luxury ::-webkit-scrollbar-track { background: var(--bg); }
.theme-luxury ::-webkit-scrollbar-thumb { background: var(--accent-2); border-radius: 9999px; }
.theme-luxury ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-luxury .label-caps { color: var(--accent); }
.theme-luxury .themed-border { border: 1px solid var(--line); outline: 1px solid oklch(0.72 0.06 85 / 15%); outline-offset: 3px; }
.theme-luxury button { transition: box-shadow 250ms ease, background 250ms ease; }
.theme-luxury button:hover { box-shadow: var(--glow); }
.theme-luxury button:active { box-shadow: none; transform: translateY(1px); }

/* alt mode: daylight atelier — ivory paper, ink stays warm, gold deepens to bronze */
.theme-luxury.alt-mode {
  --bg: oklch(0.98 0.007 78.1);
  --surface: oklch(0.955 0.007 78.1);
  --surface-2: oklch(0.92 0.007 78.1);
  --fg: oklch(0.24 0.015 80);
  --fg-muted: oklch(0.48 0.03 80);
  --accent: oklch(0.52 0.1 85);
  --accent-fg: oklch(0.98 0.007 78.1);
  --accent-2: oklch(0.62 0.08 84);
  --line: oklch(0.52 0.08 85 / 35%);
  --glow: 0 0 0 1px var(--line), 0 0 24px -12px oklch(0.52 0.1 85 / 45%);
  --shadow-1: 0 1px 0 oklch(0.52 0.08 85 / 25%);
  --shadow-2: 0 14px 34px -22px oklch(0.3 0.03 80 / 45%);
  --shadow-3: 0 28px 64px -30px oklch(0.3 0.03 80 / 50%);
  background-image: radial-gradient(60rem 40rem at 50% -20%, oklch(0.82 0.12 88 / 14%), transparent 70%);
  background-attachment: fixed;
}
/* readability guard: signature h1 is hardcoded cream — flip it to ink on ivory */
.theme-luxury.alt-mode h1 { color: oklch(0.24 0.015 80); }
.theme-luxury.alt-mode h2 { color: var(--accent); }
.theme-luxury.alt-mode ::selection { background: oklch(0.52 0.1 85); color: oklch(0.98 0.007 78.1); }
.theme-luxury.alt-mode td { border-bottom-color: oklch(0.52 0.08 85 / 18%); }
.theme-luxury.alt-mode tbody tr:hover { background: oklch(0.52 0.1 85 / 7%); }
.theme-luxury.alt-mode kbd { background: var(--surface-2); color: var(--accent); }
.theme-luxury.alt-mode ::-webkit-scrollbar-track { background: var(--bg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
